import{_ as i,h as E,i as e,c as o,v as l,p as s,x as t,m as n,e as p,S as d}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"隐式反馈：点选与停留","description":"","frontmatter":{"title":"隐式反馈：点选与停留","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/implicit-feedback-prefs.md","filePath":"llm/implicit-feedback-prefs.md","lastUpdated":1788454257000}'),m={name:"llm/implicit-feedback-prefs.md"};function A(h,a,c,B,_,P){const r=E("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="隐式反馈-点选与停留" tabindex="-1">隐式反馈：点选与停留 <a class="header-anchor" href="#隐式反馈-点选与停留" aria-label="Permalink to &quot;隐式反馈：点选与停留&quot;">​</a></h1><div class="epigraph"><p>点击、停留、复制、再生成是行为，不是成对偏好。它们经过位置、习惯与界面形状的混淆，直接塞进 Bradley-Terry，学到的是「怎么被点」，不是「哪一条更好」。</p><footer>—— 对照 Askell 等把显式 HHH 比较当实验室信号、Bai 等 HH-RLHF 用成对标注，以及搜索与推荐里点选偏置的经典处理</footer></div><p>聊天产品天然产生大量隐式日志：用户点了哪一条候选、在哪一段停留、是否复制、是否点再生成、是否给了拇指。把这些当成免费的 RLHF 数据很诱人。HH-RLHF 与 InstructGPT 用的是显式成对比较：标注员按指南在同一 \\(x\\) 下看两条 \\(y\\)。隐式反馈的生成过程完全不同：用户没看完全集、受位置与长度影响、目标是自己的任务完成而不是 HHH 指南。本篇写点选与停留能当什么特征、不能当什么金标、以及若要进偏好学习必须先做什么偏置校正。不把日志设计写成诱导用户暴露隐私的步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>显式比较近似于：在固定展示下问 \\(P(y_w \\succ y_l \\mid x, \\text{指南})\\)。隐式点选近似于：在某种排列 \\(\\pi\\) 下，用户停止搜索的行为。搜索文献里，位置偏置（靠前的更容易点）、信任偏置（更相信「官方」槽位）、停留时间与文档长度相关，早已是标准混淆。对话里还有：第一条流式输出占满屏幕、用户复制代码块不等于整段都好、再生成可能是好奇而不是不满、拇指下行是宣泄。</p><p>若把「被点的当 \\(y_w\\)、没被点的当 \\(y_l\\)」，RM 会学会占位、变长、迎合用户已表达的立场——后一项直接通向 <a href="/llm/sycophancy">谄媚</a>。Askell 的实验室信号是指南下的显式判断；用隐式去冒充 HHH，是换了数据生成过程却沿用同一损失名。</p><h3 id="停留不是满意度" tabindex="-1">停留不是满意度 <a class="header-anchor" href="#停留不是满意度" aria-label="Permalink to &quot;停留不是满意度&quot;">​</a></h3><p>停留时长与 token 数、代码块、表格、是否需要滚动强相关。长而空的回答可以「住」很久。短而正确的回答停留短。把 dwell 当正奖励，等于再引入一条 <a href="/llm/length-bias-rm">长度偏置</a>，而且比显式比较更脏，因为没有「请忽略冗长」的指南句。可用的代理应归一化：按长度、按是否复制关键跨度、按后续是否继续追问同一任务。未归一化的 dwell 不应单独作为 \\(r\\)。</p><p><span class="marginnote">隐式数据的同意与保留策略是产品约束，不是模型约束。能进训练的日志必须是用户协议覆盖、可删除、按租户隔离的。本篇只谈统计偏置，不谈如何最大化采集。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先当漏斗特征，再当偏好。漏斗：展示 → 点击/采用 → 任务成功（若有下游标签）。只有最后一层接近「有用」。中间层用于分析界面，不用于直接 BT。若要构造对：同一 \\(x\\) 下用户选中的 \\(y\\) 对随机未选 \\(y\\)，必须做位置随机化或 IPS（逆倾向加权）：记录当时的展示位置与策略，否则位置是未观测混杂。倾向为零的动作不能靠加权救回来，需要探索（偶发打乱候选顺序），这与在线学习的安全探索预算绑定。</p><p>停留：用「是否复制代码 / 是否把助手文本贴进下一轮」等稀疏采用事件，比秒数更干净。再生成：把「再生成后采用的那一条」对「被丢弃的第一条」做成对，仍要控制长度与位置。拇指：量少、极端情绪多，适合当抽检触发器，不适合当主训练集。任何隐式对都要在专家或众包金标子集上测一致率，过低则停用。</p>',12)),(e(),s(d,null,{default:t(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E5%B1%95%E7%A4%BA%E6%97%A5%E5%BF%97%EF%BC%9A%E4%BD%8D%E7%BD%AE%20%2F%20%E9%95%BF%E5%BA%A6%20%2F%20%E9%87%87%E7%94%A8%22%5D%20--%3E%20COR%5B%22%E5%81%8F%E7%BD%AE%E6%A0%A1%E6%AD%A3%EF%BC%9A%E9%9A%8F%E6%9C%BA%E5%8C%96%E6%88%96%20IPS%22%5D%0A%20%20COR%20--%3E%20PAIR%5B%22%E8%B0%A8%E6%85%8E%E6%9E%84%E9%80%A0%E7%9A%84%E5%AF%B9%22%5D%0A%20%20PAIR%20--%3E%20AUD%5B%22%E4%B8%8E%E6%98%BE%E5%BC%8F%E9%87%91%E6%A0%87%E4%BA%A4%E5%8F%89%22%5D%0A%20%20AUD%20--%3E%7C%22%E4%B8%80%E8%87%B4%E7%8E%87%E8%BF%87%E4%BD%8E%22%7C%20DROP%5B%22%E4%B8%8D%E8%BF%9B%20RM%22%5D%0A%20%20AUD%20--%3E%7C%22%E5%8F%AF%E7%94%A8%22%7C%20RM%5B%22%E5%BC%B1%E5%8A%A0%E6%9D%83%E5%81%8F%E5%A5%BD%E6%88%96%E6%8E%92%E5%BA%8F%E7%89%B9%E5%BE%81%22%5D%0A%20%20GOLD%5B%22HHH%20%E6%98%BE%E5%BC%8F%E6%AF%94%E8%BE%83%22%5D%20--%3E%20RM%0A%20%20RM%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>与 <a href="/llm/aif-as-preference">AI 反馈</a> 的关系：两者都是「非经典人类成对」，但生成过程不同。CAI 有书面原则；隐式没有原则，只有行为。不要把点击当宪法执行。与 <a href="/llm/expert-vs-crowd">专家众包</a> 的关系：隐式用户更像未培训众包，且带界面混淆。</p><h3 id="离线评估先于进训练" tabindex="-1">离线评估先于进训练 <a class="header-anchor" href="#离线评估先于进训练" aria-label="Permalink to &quot;离线评估先于进训练&quot;">​</a></h3><p>在把隐式对喂给 RM 之前，用已有显式持有集做诊断：隐式胜者在金标上的胜率是否高于 0.5，按长度分层后是否还在。若只在长回答层有效，说明仍是长度。再做反事实：把历史展示顺序打乱后的模型点击率（若有随机化记录）是否支持同一 RM。没有随机化日志时，承认因果不可识别，隐式最多当特征、不当标签。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设用户效用为 \\(u(x,y)\\)，展示位置为 \\(k\\)，点击模型常写成 \\(P(\\mathrm{click}\\mid y,k)=P(\\mathrm{exam}\\mid k)\\,P(\\mathrm{rel}\\mid y)\\) 一类分解。观测到的点击似然把 \\(P(\\mathrm{exam})\\) 和 \\(P(\\mathrm{rel})\\) 缠在一起。直接 BT 等于假定 \\(P(\\mathrm{exam})=1\\)。策略随后优化点击，会把质量预算花在靠前槽位的诱饵上：先给结论句、先给列表，即使后半段更差。停留机制类似：解码越长，观测时间期望上升，与质量无关的项进入奖励。</p><p>RLHF 的 KL 项拴的是 SFT 邻域，不校正点击模型的混杂。因此隐式进 PPO 比进分析仪表盘危险得多：仪表盘错了可以改查询，PPO 会把偏置写进权重。弱使用方式是：隐式只用于样本加权或主动学习（选哪些 \\(x\\) 送去显式标注），显式仍定义 \\(y_w\\)。</p><p><span class="marginnote">「采用」若定义为复制，代码助手里会奖励能编译的片段，这有时接近真有用；开放聊天里复制可能只是引用模型的错句去吐槽。采用的定义必须按产品线分开写。</span></p><h3 id="谄媚与隐式闭环" tabindex="-1">谄媚与隐式闭环 <a class="header-anchor" href="#谄媚与隐式闭环" aria-label="Permalink to &quot;谄媚与隐式闭环&quot;">​</a></h3><p>用户更愿意点符合自己当前表述的回答。隐式闭环会强化附和。这与显式 HHH 里诚实轴冲突。缓解不是在文档里写诱导测试题，而是在协议上：隐式有用信号不得单独用于争议事实与用户已表明立场的题；这类 \\(x\\) 只走显式诚实探针。评测报告「用户纠错后模型是否改口」的错误率即可，不描述如何构造谄媚提示。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>多候选展示（并排 A/B）比单条流式更接近比较，但仍有左槽优势。单条对话里的拇指几乎不可识别成对。工具调用产品应用下游成功（测试通过、工单关闭）当更硬的奖励，点击降级为调试信号。隐私：隐式比显式示范更容易含个人数据，清洗与保留期限要更严，不能因为「不是用户写的偏好句」就放松。</p><p>不要用隐式去标无害。用户在有害请求上的「采用」恰恰可能是政策失败。无害只走政策比较、CAI 或专家，见 HH-RLHF 与 Constitutional AI。隐式最多提示「这类 \\(x\\) 很频繁」，把频繁项送去安全队列。</p><p><span class="marginnote">搜索广告里的点击模型经过二十年校正仍会偏。对话日志更短、更非平稳。预期应是：隐式改善抽样效率，不替代 Askell/Bai 路线上的显式轴。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点选与停留是带位置、长度、界面混淆的行为，不是指南下的成对偏好。</li><li>未做随机化或 IPS 的点击对不应直接训 RM；dwell 必须按长度与采用事件归一化。</li><li>隐式适合漏斗分析、主动学习加权；HHH 金标仍应是显式比较或原则化 AI 反馈。</li><li>采用定义按产品线分开；无害轴禁止用隐式采用当正例。</li><li>闭环点击会放大谄媚与长度，评测用金标交叉而不是在线点击率单独报喜。</li><li>出处：Askell et al., 2021；Bai et al., HH-RLHF / Constitutional AI, 2022；点选偏置传统见信息检索的位置偏置与 IPS 实践。</li></ul>',15))])}const H=i(m,[["render",A]]);export{u as __pageData,H as default};
